// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // fuzzed params: from address, array length (as uint8) and a failing switch
    function testFuzz_property(address from, uint8 tosLen, bool shouldFail) public {
        // keep tosLen small but allow zero to be rejected by require in C
        uint256 len = bound(tosLen, 0, 5);

        // build arrays
        address[] memory tos = new address[](len);
        uint256[] memory vals = new uint256[](len);
        for (uint i = 0; i < len; i++) {
            // deploy a recorder/reverter helper for each entry that can be set to fail or succeed
            // but to keep things simple and within fuzzing, reuse one helper and set its mode
            // We'll deploy one helper and use its address for all calls
            tos[i] = address(0xBEEF);
            vals[i] = uint256(i + 1);
        }

        // Deploy a helper that can be toggled to revert or succeed. The helper exposes transferFrom to match selector.
        CalleeHelper helper = new CalleeHelper();
        // set its mode according to fuzzed shouldFail
        helper.setShouldFail(shouldFail);

        // If length is zero, reference contract reverts due to require(_tos.length > 0).
        // Both reference and mutant behave the same for len==0, so allow fuzz to include it.

        // Replace placeholder addresses with helper address so C will call it
        for (uint i = 0; i < len; i++) {
            tos[i] = address(helper);
        }

        // Attempt the transfer and observe whether it reverted
        bool ok;
        try c.transfer(from, address(helper), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): The reference implementation always reverts (ok==false)
        // whenever any external transferFrom call fails. We trigger that by setting shouldFail==true and len>0.
        // So assert that when we asked the helper to fail and there is at least one recipient, the call did NOT succeed.
        if (shouldFail && len > 0) {
            assertTrue(!ok);
        } else {
            // otherwise the reference may succeed (len>0 & !shouldFail) or revert due to empty tos.
            // We cannot assert a single outcome here; only the above branch is required to distinguish mutant.
            assertTrue(true);
        }
    }
}

// Helper that matches the called selector: transferFrom(address,address,uint256)
contract CalleeHelper {
    bool public shouldFail;
    // record calls if needed
    event Called(address from, address to, uint256 v);

    function setShouldFail(bool b) external { shouldFail = b; }

    // This function matches the selector used by C and will either revert or emit an event and return
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        emit Called(from, to, v);
        if (shouldFail) {
            revert("forced fail");
        }
        return true;
    }
}
